Azure API Management.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Azure API Management container

Container_Boundary(apim, "Azure API Management") {
    Component(api_gateway_engine, "API Gateway Engine", "Azure API Management Policy Engine", "Handles edge security, rate limiting, versioning, routing, and applies retry/circuit-breaker policies.")
    Component(auth_handler, "Authentication & Authorization Handler", "OpenID Connect / OAuth2", "Validates tokens for SSO against Corporate Active Directory.")
    Component(diagnostic_publisher, "Diagnostic & Telemetry Publisher", "HTTPS", "Streams diagnostic logs and telemetry to Azure Monitor and Application Insights.")
}

Rel(api_gateway_engine, auth_handler, "Validates tokens via OpenID Connect / OAuth2", "OIDC/OAuth2")
Rel(api_gateway_engine, diagnostic_publisher, "Streams diagnostic logs and telemetry via HTTPS", "HTTPS")

@enduml

Azure Service Bus.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(azure_service_bus, "Azure Service Bus") {
    Component(Claims_Topic, "Claims-Topic", "Azure Service Bus Topic", "Publishes and distributes claim events across the processing core and integration layers.")
    Component(Mainframe_Sync_Queue, "Mainframe-Sync-Queue", "Azure Service Bus Queue", "Relays batched sync payloads to the legacy mainframe via Azure Hybrid Connection.")
    Component(Audit_Relay, "Audit-Relay", "Azure Service Bus Queue/Topic", "Captures and routes audit trails to the compliance archive.")
    Component(DLQ_Replay_Processor, "DLQ-Replay-Processor", "Azure Service Bus Dead-Letter Queue Processor", "Listens to the dead-letter queue and triggers message replays for failed claim transactions.")
}

Rel(Claims Processing Core, Claims_Topic, "Publishes claim events", "AMQP over TLS")
Rel(Mainframe_Sync_Queue, Legacy Mainframe, "Relays batched sync payloads", "HTTPS / Azure Hybrid Connection")
Rel(DLQ_Replay_Processor, DLQ, "Listens and triggers replays", "AMQP")
@enduml
